<?php
/**
 * SSP AJAX Prompt Builder Trait - Smart prompt templates for product generation
 */
trait SSP_AjaxPromptBuilder {

    public function handle_save_prompt_template() {
        $user_id = $this->ajax_require_auth();
        if ($this->get_user_plan($user_id) !== 'pro') wp_send_json_error(['message' => 'ذخیره قالب پرامپت فقط در پلن Pro موجود است']);
        $templates = $this->get_user_prompt_templates($user_id);
        if (count($templates) >= 20) wp_send_json_error(['message' => 'حداکثر ۲۰ قالب پرامپت می‌توانید ذخیره کنید']);
        $id = isset($_POST['template_id']) ? intval($_POST['template_id']) : 0;
        $data = [
            'name' => sanitize_text_field($_POST['name'] ?? 'قالب جدید'),
            'type' => sanitize_text_field($_POST['type'] ?? 'product'),
            'industry' => sanitize_textarea_field($_POST['industry'] ?? ''),
            'tone' => sanitize_textarea_field($_POST['tone'] ?? ''),
            'general_rules' => sanitize_textarea_field($_POST['general_rules'] ?? ''),
            'short_rules' => sanitize_textarea_field($_POST['short_rules'] ?? ''),
            'long_rules' => sanitize_textarea_field($_POST['long_rules'] ?? ''),
            'seo_rules' => sanitize_textarea_field($_POST['seo_rules'] ?? ''),
            'focus' => sanitize_textarea_field($_POST['focus'] ?? ''),
            'forbidden' => sanitize_textarea_field($_POST['forbidden'] ?? ''),
            'extra' => sanitize_textarea_field($_POST['extra'] ?? ''),
            'is_default' => intval($_POST['is_default'] ?? 0),
        ];
        // If editing a built-in template (negative ID), always create a new user template
        if ($id < 0) {
            $id = 0;
        }
        if ($id > 0) {
            $found = false;
            foreach ($templates as &$t) {
                if ((int)$t['id'] === $id) {
                    $data['id'] = $id;
                    $data['created_at'] = $t['created_at'] ?? current_time('mysql');
                    $t = $data;
                    $found = true;
                    break;
                }
            }
            unset($t);
            if (!$found) wp_send_json_error(['message' => 'قالب یافت نشد']);
        } else {
            $data['id'] = $this->next_id($templates);
            $data['created_at'] = current_time('mysql');
            $templates[] = $data;
        }
        if (!empty($data['is_default'])) {
            foreach ($templates as &$t) {
                if ((int)$t['id'] !== $data['id']) $t['is_default'] = 0;
            }
            unset($t);
        }
        $this->set_user_items($user_id, 'prompt_templates', $templates);
        wp_send_json_success(['message' => 'قالب ذخیره شد!', 'id' => $data['id']]);
    }

    public function handle_get_prompt_templates() {
        $user_id = $this->ajax_require_auth();
        $templates = $this->get_user_prompt_templates($user_id);
        $builtin = $this->get_builtin_prompt_templates();
        // Always include all built-in templates so they can be used for reset functionality
        // User templates with same name will have positive IDs, built-ins have negative IDs
        foreach ($builtin as $b) {
            $templates[] = $b;
        }
        wp_send_json_success(['templates' => $templates]);
    }

    public function handle_delete_prompt_template() {
        $user_id = $this->ajax_require_auth();
        $templates = $this->get_user_prompt_templates($user_id);
        $id = intval($_POST['template_id']);
        if ($id <= 0) wp_send_json_error(['message' => 'قالب‌های پیش‌فرض قابل حذف نیستند']);
        $templates = array_values(array_filter($templates, function($t) use ($id) { return (int)$t['id'] !== $id; }));
        $this->set_user_items($user_id, 'prompt_templates', $templates);
        wp_send_json_success(['message' => 'قالب حذف شد']);
    }

    public function handle_preview_prompt() {
        $user_id = $this->ajax_require_auth();
        $product_name = sanitize_text_field($_POST['product_name'] ?? '');
        if (empty($product_name)) wp_send_json_error(['message' => 'نام محصول را وارد کنید']);
        $template_id = intval($_POST['template_id'] ?? 0);
        $templates = $this->get_user_prompt_templates($user_id);
        if ($template_id < 0) {
            $templates = array_merge($templates, $this->get_builtin_prompt_templates());
        }
        $template = null;
        foreach ($templates as $t) {
            if ((int)$t['id'] === $template_id) { $template = $t; break; }
        }
        if (!$template) wp_send_json_error(['message' => 'قالب یافت نشد']);
        $prompt = $this->build_prompt_from_template($template, $product_name);
        wp_send_json_success(['prompt' => $prompt]);
    }

    private function get_user_prompt_templates($user_id) {
        return $this->get_user_items($user_id, 'prompt_templates');
    }

    private function build_prompt_from_template($template, $product_name, $product_brief = '') {
        $is_article = ($template['type'] ?? 'product') === 'article';
        $parts = [
            "دستورالعمل سیستمی: تو یک متخصص و استراتژیست ارشد تولید محتوای وب و سئو هستی. محتوای خروجی باید کاملاً معتبر، واقعی، روان، غنی و بدون گزافه‌گویی باشد. هرگز هیچ مقدمه، احوالپرسی، توضیح اضافی، تگ تفکر، یا کاراکتر قبل/بعد از ساختار JSON تولید نکن.",
            $is_article ? "موضوع مقاله: {$product_name}" : "نام محصول: {$product_name}"
        ];
        if (!empty($product_brief)) $parts[] = "توضیحات و نکات تکمیلی: {$product_brief}";
        if (!empty($template['industry'])) $parts[] = "حوزه تخصصی / صنعت: {$template['industry']}";
        if (!empty($template['tone'])) $parts[] = "لحن نوشتار: {$template['tone']}";
        if (!empty($template['general_rules'])) $parts[] = "\nقوانین عمومی نگارش:\n{$template['general_rules']}";
        if ($is_article) {
            if (!empty($template['short_rules'])) $parts[] = "\n--- ساختار و بخش‌های مقاله ---\n{$template['short_rules']}";
            if (!empty($template['long_rules'])) $parts[] = "\n--- الزامات محتوایی و نگارشی ---\n{$template['long_rules']}";
            if (!empty($template['seo_rules'])) $parts[] = "\n--- تنظیمات و کلمات کلیدی سئو ---\n{$template['seo_rules']}";
            $json_format = <<<'JSON'
دستور اکید: پاسخ شما باید ۱۰۰٪ منحصراً یک شیء معتبر JSON خالص بدون هیچ متن اضافی قبل یا بعد از آن با کلیدهای زیر باشد:
{
  "title": "عنوان جذاب، گیرا و سئو شده برای مقاله (حداکثر ۷۰ کاراکتر)",
  "content": "محتوای کامل، عمیق و سئو شده مقاله با ساختار استاندارد HTML شامل h2, h3, p, ul/li, strong و جداول مرتبط (حداقل ۸۰۰ کلمه)",
  "excerpt": "خلاصه جذاب و ترغیب‌کننده ۲ تا ۳ جمله‌ای برای پیش‌نمایش مقاله",
  "categories": ["دسته‌بندی مرتبط ۱", "دسته‌بندی مرتبط ۲"],
  "tags": ["برچسب ۱", "برچسب ۲", "برچسب ۳", "برچسب ۴"],
  "meta_title": "تیتر سئو حداکثر ۶۰ کاراکتر",
  "meta_description": "توضیحات متا سئو حداکثر ۱۶۰ کاراکتر"
}
JSON;
        } else {
            if (!empty($template['short_rules'])) $parts[] = "\n--- توضیحات کوتاه (short_description) ---\n{$template['short_rules']}";
            if (!empty($template['long_rules'])) $parts[] = "\n--- توضیحات بلند (description) ---\n{$template['long_rules']}";
            if (!empty($template['seo_rules'])) $parts[] = "\n--- تنظیمات و کلمات کلیدی سئو ---\n{$template['seo_rules']}";
            $json_format = <<<'JSON'
دستور اکید: پاسخ شما باید ۱۰۰٪ منحصراً یک شیء معتبر JSON خالص بدون هیچ متن اضافی قبل یا بعد از آن با کلیدهای زیر باشد:
{
  "name": "نام دقیق، تجاری و سئو شده محصول به فارسی (حداکثر ۶۰ کاراکتر)",
  "sku": "کد انبار انگلیسی یکتا مانند PRD-8520",
  "short_description": "توضیحات کوتاه، جذاب و ترغیب‌کننده به صورت HTML تمیز در ۲ تا ۳ جمله",
  "description": "توضیحات بسیار جامع با ساختار حرفه‌ای HTML شامل <h2>معرفی و بررسی تخصصی محصول</h2>، <p>متن کامل معرفی</p>، <h3>ویژگی‌ها و مزایای کلیدی</h3><ul><li>ویژگی ۱</li><li>ویژگی ۲</li><li>ویژگی ۳</li></ul>، <h3>مشخصات فنی و کاربردی</h3>، <h3>راهنمای استفاده و شرایط گارانتی</h3>",
  "regular_price": "قیمت اصلی به عدد تومان مثلا 450000",
  "sale_price": "قیمت تخفیف‌خورده به عدد تومان یا خالی",
  "weight": "0.5",
  "categories": ["دسته‌بندی اصلی ۱", "دسته‌بندی فرعی ۲"],
  "tags": ["برچسب ۱", "برچسب ۲", "برچسب ۳"],
  "meta_title": "تیتر سئو حداکثر ۶۰ کاراکتر",
  "meta_description": "توضیحات متا سئو جذاب حداکثر ۱۵۰ کاراکتر",
  "slug": "اسلاگ-انگلیسی-کوتاه"
}
JSON;
        }
        if (!empty($template['focus'])) $parts[] = "\nتمرکز اصلی: {$template['focus']}";
        if (!empty($template['forbidden'])) $parts[] = "ممنوعیات: {$template['forbidden']}";
        if (!empty($template['extra'])) $parts[] = "زمینه و راهنمای تخصصی: {$template['extra']}";
        $parts[] = "\n{$json_format}";
        return implode("\n", $parts);
    }

    private function get_builtin_prompt_templates() {
